  /// Rata-rata peluang stunting (kelas "Yes") dari seluruh pohon, 0.0 - 1.0.
  static double predictProbaYes(List<double> x) {
    if (x.length != 7) {
      throw ArgumentError('Fitur harus 7 nilai, diterima ${x.length}');
    }
    // scikit-learn membulatkan input ke float32 sebelum dibandingkan dengan
    // threshold; Float32List meniru perilaku itu agar hasil identik.
    final f = Float32List.fromList(x);
    var sum = 0.0;
    for (final root in _roots) {
      var i = root;
      while (_feature[i] >= 0) {
        i = f[_feature[i]] <= _threshold[i] ? _left[i] : _right[i];
      }
      sum += _leafProb[i];
    }
    return sum / _roots.length;
  }
